/*
09 Christmas Snow Globe Showcase
Pure Canvas 2D | 25 seconds | 2 scenes | 16:9 | UHD 3840 x 2160
Time Motion Studio: time is in SECONDS. Call draw(ctx, time, width, height).
Self-contained and deterministic; no assets, DOM, libraries or animation scheduler.
Scene 1: 0 - 12.5 s. Scene 2: 12.5 - 25 s. Scene handoff: 1.75 s.
Loop: continuing periodic motion and a smooth return of the scene arrangement.
COPY_SPACE_SAFE_RECT_1920x1080: [131, 192, 940, 734]
No glow, bloom, neon, shadow or filter effects. All colors are solid vector fills.
VIDEO_EXPORT: 3840 x 2160, 60 fps recommended, video bitrate 100 Mbps or higher.
Bitrate must be set by the video encoder; JavaScript draw() does not encode video.
*/
function draw(ctx, time, width, height) {
  if (!(width > 0 && height > 0) || !Number.isFinite(time)) return;

  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount; // 12.5 s
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const localT = sceneProgress * sceneDuration;

  const minSide = Math.min(width, height);
  const unit = minSide / 1080;
  const viewWidth = width / unit;
  const viewHeight = height / unit;

  const TAU = Math.PI * 2;
  const phase = (TAU * loopT) / duration;

  // Smoothing, easing, and utility functions
  const clamp = x => Math.max(0, Math.min(1, x));
  const ease = x => {
    x = clamp(x);
    return x * x * x * (x * (6 * x - 15) + 10); // Quintic smootherstep
  };
  const hash = i => {
    const q = Math.sin(i * 127.1 + 311.7) * 43758.5453123;
    return q - Math.floor(q);
  };
  const wave = (cycles, offset = 0) => Math.sin(phase * cycles + offset);

  // Controlled 1.75s handoff transition
  const handoffDuration = 1.75;
  const handoffStart = sceneDuration - handoffDuration;
  const rawHandoff = localT >= handoffStart ? (localT - handoffStart) / handoffDuration : 0;
  const handoff = ease(rawHandoff);

  // Crossfade opacities: alphaScene1 + alphaScene2 === 1 at all times
  let alphaScene1 = 0;
  let alphaScene2 = 0;
  if (currentScene === 0) {
    alphaScene1 = 1 - handoff;
    alphaScene2 = handoff;
  } else {
    alphaScene1 = handoff;
    alphaScene2 = 1 - handoff;
  }

  // Consistent holiday vector color palette
  const palette = {
    pine: '#245747',
    pineDark: '#173E36',
    sage: '#719883',
    mint: '#BDD0BD',
    red: '#A43C43',
    wine: '#773B48',
    coral: '#C96862',
    cream: '#F4EBDD',
    ivory: '#FAF5EC',
    gold: '#B79A60',
    goldLight: '#D8C18A',
    navy: '#25394D',
    blue: '#7D9AAA',
    ice: '#DFEAF0',
    white: '#FFFDF7'
  };

  ctx.save();
  try {
    ctx.setTransform(unit, 0, 0, unit, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    if ('filter' in ctx) ctx.filter = 'none';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // Canvas background fill
    ctx.fillStyle = '#F4F0E7';
    ctx.fillRect(0, 0, viewWidth, viewHeight);

    // Uniform 1920x1080 centering
    ctx.translate((viewWidth - 1920) / 2, (viewHeight - 1080) / 2);

    // --- Geometry & Vector Drawing Primitives ---
    function circle(x, y, r, fill) {
      ctx.beginPath();
      ctx.arc(x, y, Math.max(0.01, r), 0, TAU);
      ctx.fillStyle = fill;
      ctx.fill();
    }

    function ellipse(x, y, rx, ry, fill) {
      ctx.beginPath();
      ctx.ellipse(x, y, Math.max(0.01, rx), Math.max(0.01, ry), 0, 0, TAU);
      ctx.fillStyle = fill;
      ctx.fill();
    }

    function line(x1, y1, x2, y2, color, weight = 3) {
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.strokeStyle = color;
      ctx.lineWidth = weight;
      ctx.stroke();
    }

    function polygon(points, color) {
      if (!points || points.length < 3) return;
      ctx.beginPath();
      ctx.moveTo(points[0][0], points[0][1]);
      for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
    }

    function box(x, y, w, h, r, color) {
      const rad = Math.max(0, Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2));
      ctx.beginPath();
      ctx.moveTo(x + rad, y);
      ctx.lineTo(x + w - rad, y);
      ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
      ctx.lineTo(x + w, y + h - rad);
      ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
      ctx.lineTo(x + rad, y + h);
      ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
      ctx.lineTo(x, y + rad);
      ctx.quadraticCurveTo(x, y, x + rad, y);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
    }

    function star(x, y, r, color, angle = 0, innerRatio = 0.44) {
      const points = [];
      for (let i = 0; i < 10; i++) {
        const a = angle - Math.PI / 2 + (i * Math.PI) / 5;
        const z = i % 2 ? r * innerRatio : r;
        points.push([x + Math.cos(a) * z, y + Math.sin(a) * z]);
      }
      polygon(points, color);
    }

    function opacity(val, drawObject) {
      ctx.save();
      ctx.globalAlpha *= clamp(val);
      drawObject();
      ctx.restore();
    }

    // --- Precise Holiday Decorative Assets ---
    function bow(x, y, size, color, accent) {
      ctx.save();
      ctx.translate(x, y);
      // Left ribbon swallowtail tail
      polygon(
        [
          [-size * 0.08, size * 0.08],
          [-size * 0.38, size * 0.72],
          [-size * 0.28, size * 0.52],
          [-size * 0.54, size * 0.64],
          [-size * 0.16, 0]
        ],
        color
      );
      // Right ribbon swallowtail tail
      polygon(
        [
          [size * 0.08, size * 0.08],
          [size * 0.38, size * 0.72],
          [size * 0.28, size * 0.52],
          [size * 0.54, size * 0.64],
          [size * 0.16, 0]
        ],
        color
      );
      // Left ribbon loop
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(-size * 0.32, -size * 0.72, -size * 0.94, -size * 0.62, -size * 0.76, -size * 0.12);
      ctx.bezierCurveTo(-size * 0.58, size * 0.16, -size * 0.18, size * 0.06, 0, 0);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
      // Right ribbon loop
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(size * 0.32, -size * 0.72, size * 0.94, -size * 0.62, size * 0.76, -size * 0.12);
      ctx.bezierCurveTo(size * 0.58, size * 0.16, size * 0.18, size * 0.06, 0, 0);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
      // Loop accent folds
      line(-size * 0.14, -size * 0.04, -size * 0.56, -size * 0.22, accent, Math.max(1.5, size * 0.05));
      line(size * 0.14, -size * 0.04, size * 0.56, -size * 0.22, accent, Math.max(1.5, size * 0.05));
      // Central knot
      box(-size * 0.15, -size * 0.14, size * 0.3, size * 0.28, 4, accent);
      ctx.restore();
    }

    function pineBranch(x, y, length, angle, color, accent) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(angle);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(length * 0.5, -8, length, 0);
      ctx.strokeStyle = accent;
      ctx.lineWidth = 3.5;
      ctx.stroke();
      const steps = 14;
      for (let i = 1; i <= steps; i++) {
        const u = i / (steps + 1);
        const px = length * u;
        const py = -8 * Math.sin(Math.PI * u);
        const reach = 16 + 20 * Math.sin(Math.PI * u);
        for (let j = 0; j < 3; j++) {
          const dx = -reach * (0.32 + j * 0.1);
          const dy = reach - j * 6.5;
          line(px, py, px + dx, py - dy, j === 1 ? accent : color, 2.6);
          line(px, py, px + dx, py + dy, j === 1 ? accent : color, 2.6);
        }
      }
      ctx.restore();
    }

    function pineCone(x, y, size, angle = 0) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(angle);
      ellipse(0, 0, size * 0.32, size * 0.52, '#7C573E');
      for (let row = 0; row < 5; row++) {
        const yy = -size * 0.32 + row * size * 0.16;
        const count = 3;
        const span = Math.sin(((row + 1) * Math.PI) / 6) * size * 0.28;
        for (let c = 0; c < count; c++) {
          const xx = -span + (c / (count - 1)) * 2 * span;
          ellipse(xx, yy, size * 0.12, size * 0.08, c % 2 === 0 ? '#B28C67' : '#9E7652');
        }
      }
      ctx.restore();
    }

    function holly(x, y, size, angle = 0) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(angle);
      [-0.65, 0.65].forEach(rot => {
        ctx.save();
        ctx.rotate(rot);
        const w = size * 0.4;
        const len = size * 0.82;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(-w * 0.8, -len * 0.3, -w * 0.4, -len * 0.5);
        ctx.quadraticCurveTo(-w, -len * 0.7, 0, -len);
        ctx.quadraticCurveTo(w, -len * 0.7, w * 0.4, -len * 0.5);
        ctx.quadraticCurveTo(w * 0.8, -len * 0.3, 0, 0);
        ctx.closePath();
        ctx.fillStyle = palette.pine;
        ctx.fill();
        line(0, 0, 0, -len * 0.9, palette.sage, 1.8);
        ctx.restore();
      });
      // Berries cluster
      circle(-size * 0.12, size * 0.05, size * 0.15, palette.red);
      circle(size * 0.12, size * 0.05, size * 0.15, palette.red);
      circle(0, size * 0.19, size * 0.14, palette.coral);
      circle(-size * 0.15, size * 0.01, size * 0.04, palette.white);
      circle(size * 0.09, size * 0.01, size * 0.04, palette.white);
      circle(-size * 0.03, size * 0.15, size * 0.04, palette.white);
      ctx.restore();
    }

    function bell(x, y, size, color, clapperAngle = 0) {
      ctx.save();
      ctx.translate(x, y);
      // Bell clapper
      ctx.save();
      ctx.translate(0, size * 0.34);
      ctx.rotate(clapperAngle);
      circle(0, size * 0.11, size * 0.085, palette.gold);
      line(0, -size * 0.14, 0, size * 0.09, palette.goldLight, 2.2);
      ctx.restore();
      // Bell body
      ctx.beginPath();
      ctx.moveTo(-size * 0.38, size * 0.34);
      ctx.bezierCurveTo(-size * 0.26, size * 0.16, -size * 0.3, -size * 0.28, 0, -size * 0.34);
      ctx.bezierCurveTo(size * 0.3, -size * 0.28, size * 0.26, size * 0.16, size * 0.38, size * 0.34);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
      // Lip and top loop
      box(-size * 0.4, size * 0.3, size * 0.8, size * 0.08, 3, palette.gold);
      circle(0, -size * 0.35, size * 0.065, palette.gold);
      circle(0, -size * 0.35, size * 0.025, '#FAF5EC');
      // Highlight rim
      ctx.beginPath();
      ctx.arc(0, 0, size * 0.25, Math.PI * 1.05, Math.PI * 1.35);
      ctx.strokeStyle = palette.goldLight;
      ctx.lineWidth = 2.4;
      ctx.stroke();
      ctx.restore();
    }

    function snowflake(x, y, r, color, angle = 0) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(angle);
      const strokeW = Math.max(1.8, r * 0.08);
      for (let i = 0; i < 6; i++) {
        ctx.save();
        ctx.rotate((i * Math.PI) / 3);
        line(0, 0, 0, -r, color, strokeW);
        line(0, -r * 0.55, -r * 0.24, -r * 0.78, color, strokeW);
        line(0, -r * 0.55, r * 0.24, -r * 0.78, color, strokeW);
        ctx.restore();
      }
      ctx.restore();
    }

    function bauble(x, y, r, color, motif = 0) {
      ctx.save();
      ctx.translate(x, y);
      circle(0, 0, r, color);
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, r - 1.5, 0, TAU);
      ctx.clip();
      if (motif === 0) {
        for (let j = -2; j <= 2; j++) {
          line(-r, j * r * 0.33, r, j * r * 0.33, palette.goldLight, r * 0.1);
        }
      } else if (motif === 1) {
        snowflake(0, 0, r * 0.55, palette.cream, 0);
      } else {
        for (let row = -1; row <= 1; row++) {
          for (let col = -1; col <= 1; col++) {
            circle(col * r * 0.48, row * r * 0.48, r * 0.08, palette.cream);
          }
        }
      }
      ctx.restore();
      // Specular shine
      ctx.beginPath();
      ctx.arc(0, 0, r - 4, Math.PI * 1.15, Math.PI * 1.5);
      ctx.strokeStyle = palette.white;
      ctx.lineWidth = 2.5;
      ctx.stroke();
      ctx.restore();
    }

    function hangingBauble(anchorX, anchorY, cordLength, r, color, motif, swingAngle) {
      ctx.save();
      ctx.translate(anchorX, anchorY);
      ctx.rotate(swingAngle);
      line(0, 0, 0, cordLength, palette.gold, 2);
      box(-r * 0.22, cordLength - 5, r * 0.44, 8, 2, palette.goldLight);
      circle(0, cordLength - 5, 3.5, palette.goldLight);
      bauble(0, cordLength + r, r, color, motif);
      ctx.restore();
    }

    function gift(x, y, w, h, color, ribbon, pattern = 0, lift = 0) {
      ctx.save();
      ctx.translate(x, y);
      // Box body
      box(0, 0, w, h, 4, color);
      ctx.save();
      box(3, 3, w - 6, h - 6, 2, color);
      ctx.clip();
      if (pattern === 0) {
        for (let yy = 16; yy < h; yy += 24) {
          for (let xx = 14; xx < w; xx += 24) circle(xx, yy, 2.4, palette.cream);
        }
      } else if (pattern === 1) {
        for (let d = -h; d < w + h; d += 26) line(d, 0, d + h, h, palette.cream, 2.5);
      } else {
        for (let yy = 18; yy < h; yy += 30) {
          for (let xx = 16; xx < w; xx += 30) star(xx, yy, 4.5, palette.goldLight);
        }
      }
      ctx.restore();
      // Ribbon cross bands on body
      box(w * 0.44, 0, w * 0.12, h, 0, ribbon);
      box(0, h * 0.42, w, Math.max(8, h * 0.14), 0, ribbon);

      // Surprise reveal when lid lifts
      if (lift > 0.01) {
        box(5, -lift * 0.65, w - 10, lift * 0.65 + 4, 2, palette.pineDark);
        star(w * 0.5, -lift * 0.5, Math.min(14, lift * 0.45 + 4), palette.goldLight, 0.05 * wave(2));
      }
      // Box Lid
      const lidH = Math.max(12, h * 0.22);
      const overhang = Math.max(3, w * 0.05);
      box(-overhang, -lift - lidH * 0.7, w + overhang * 2, lidH, 3, color);
      box(w * 0.44, -lift - lidH * 0.7, w * 0.12, lidH, 0, ribbon);
      bow(w * 0.5, -lift - lidH * 0.7, Math.min(w * 0.3, 36), ribbon, palette.goldLight);
      ctx.restore();
    }

    function fir(x, baseY, h, color, decorated = false) {
      const trunkW = h * 0.08;
      const trunkH = h * 0.16;
      box(x - trunkW / 2, baseY - trunkH, trunkW, trunkH, 2, '#8E6C4C');
      const tiers = [
        { bottomY: baseY - trunkH * 0.7, topY: baseY - h * 0.5, w: h * 0.62 },
        { bottomY: baseY - h * 0.4, topY: baseY - h * 0.74, w: h * 0.46 },
        { bottomY: baseY - h * 0.66, topY: baseY - h, w: h * 0.3 }
      ];
      tiers.forEach(tr => {
        polygon(
          [
            [x, tr.topY],
            [x - tr.w * 0.5, tr.bottomY],
            [x + tr.w * 0.5, tr.bottomY]
          ],
          color
        );
        line(x - tr.w * 0.48, tr.bottomY - 1, x + tr.w * 0.48, tr.bottomY - 1, palette.white, Math.max(3, h * 0.022));
      });
      if (decorated) {
        star(x, baseY - h - 4, h * 0.075, palette.goldLight);
        star(x, baseY - h - 4, h * 0.04, palette.gold);
        [0.45, 0.68].forEach((p, idx) => {
          const swY = baseY - h * p;
          const swW = h * (idx === 0 ? 0.38 : 0.24);
          ctx.beginPath();
          ctx.moveTo(x - swW * 0.5, swY - 6);
          ctx.quadraticCurveTo(x, swY + 8, x + swW * 0.5, swY - 6);
          ctx.strokeStyle = palette.goldLight;
          ctx.lineWidth = 2.2;
          ctx.stroke();
        });
        const ornaments = [
          { dx: -0.16, dy: 0.22, c: palette.coral },
          { dx: 0.15, dy: 0.24, c: palette.goldLight },
          { dx: -0.09, dy: 0.38, c: palette.mint },
          { dx: 0.11, dy: 0.48, c: palette.coral },
          { dx: -0.12, dy: 0.58, c: palette.goldLight },
          { dx: 0.07, dy: 0.72, c: palette.mint }
        ];
        ornaments.forEach(o => {
          circle(x + o.dx * h, baseY - o.dy * h, Math.max(3.2, h * 0.022), o.c);
        });
      }
    }

    function house(x, baseY, w, h, color, smokePuffs = []) {
      const bodyH = h * 0.55;
      const bodyY = baseY - bodyH;
      box(x - w / 2, bodyY, w, bodyH, 3, color);
      for (let s = 1; s <= 3; s++) {
        line(x - w / 2 + 4, bodyY + s * (bodyH / 4), x + w / 2 - 4, bodyY + s * (bodyH / 4), '#5A2A32', 1.8);
      }
      const doorW = w * 0.18;
      const doorH = bodyH * 0.62;
      box(x - doorW / 2, baseY - doorH, doorW, doorH, 3, palette.pineDark);
      circle(x + doorW * 0.25, baseY - doorH * 0.45, 2, palette.goldLight);
      const winW = w * 0.2;
      const winH = bodyH * 0.42;
      const winY = bodyY + bodyH * 0.2;
      [-w * 0.28, w * 0.28].forEach(wx => {
        box(x + wx - winW / 2, winY, winW, winH, 2, palette.goldLight);
        line(x + wx, winY, x + wx, winY + winH, color, 1.8);
        line(x + wx - winW / 2, winY + winH / 2, x + wx + winW / 2, winY + winH / 2, color, 1.8);
      });
      const chimW = w * 0.13;
      const chimH = h * 0.34;
      const chimX = x + w * 0.24;
      const chimY = baseY - h * 0.92;
      box(chimX, chimY, chimW, chimH, 1, '#654B3E');
      box(chimX - 2, chimY - 3, chimW + 4, 6, 2, palette.white);
      smokePuffs.forEach(puff => {
        opacity(puff.alpha, () => circle(puff.x, puff.y, puff.r, palette.white));
      });
      const roofPeakY = baseY - h;
      const roofOverhang = w * 0.12;
      polygon(
        [
          [x, roofPeakY],
          [x - w / 2 - roofOverhang, bodyY],
          [x + w / 2 + roofOverhang, bodyY]
        ],
        palette.pineDark
      );
      line(x, roofPeakY - 2, x - w / 2 - roofOverhang, bodyY + 2, palette.white, 7);
      line(x, roofPeakY - 2, x + w / 2 + roofOverhang, bodyY + 2, palette.white, 7);
    }

    function boundedSnow(regions, count, color, offset = 0) {
      for (let i = 0; i < count; i++) {
        const region = regions[i % regions.length];
        const cycles = 3 + (i % 2);
        const u = ((loopT * cycles) / duration + hash(i + offset)) % 1;
        const a = ease(u / 0.15) * ease((1 - u) / 0.15);
        const xx = region[0] + 8 + hash(i + offset + 51) * (region[2] - 16) + 4 * wave(2, i);
        const yy = region[1] + 6 + u * (region[3] - 12);
        opacity(a * 0.65, () => circle(xx, yy, 1.8 + hash(i + offset + 97) * 2.0, color));
      }
    }

    // --- Snow Globe Presentation Anchor & Sizing ---
    const globeX = 1480;
    const globeY = 575;
    const radius = 265;

    // Ground contact shadow
    ellipse(globeX, 955, 240, 10, '#E3DAD0');

    // Globe Base & Pedestal
    box(globeX - 235, 922, 470, 26, 6, palette.pineDark);
    box(globeX - 215, 860, 430, 64, 10, palette.pine);
    line(globeX - 195, 892, globeX + 195, 892, palette.sage, 2);
    circle(globeX, 892, 11, palette.gold);
    star(globeX, 892, 8, palette.goldLight);
    box(globeX - 195, 852, 390, 8, 3, palette.gold);
    box(globeX - 180, 822, 360, 32, 8, palette.pineDark);
    line(globeX - 170, 826, globeX + 170, 826, palette.sage, 1.8);

    // Glass Interior
    circle(globeX, globeY, radius, '#DFEAF0');

    ctx.save();
    ctx.beginPath();
    ctx.arc(globeX, globeY, radius - 6, 0, TAU);
    ctx.clip();

    // Snow Dunes inside the Globe
    ellipse(globeX, 842, 260, 58, '#D8E5E0');
    ellipse(globeX - 50, 856, 230, 52, '#E8F2EE');
    ellipse(globeX + 40, 868, 250, 46, palette.white);

    // --- SCENE 1: Christmas Tree & Gift Vignette ---
    if (alphaScene1 > 0.001) {
      opacity(alphaScene1, () => {
        fir(globeX, 824, 255, palette.pine, true);
        gift(globeX - 118, 786, 56, 44, palette.red, palette.goldLight, 0, 0);
        gift(globeX + 66, 780, 54, 50, palette.gold, palette.cream, 1, 0);
        // Center front gift gentle unboxing breathing motion
        const giftLiftCycle = ease(0.5 + 0.5 * Math.sin(phase * 4 - Math.PI / 2));
        const giftLift = 8 * giftLiftCycle;
        gift(globeX - 22, 804, 44, 32, palette.wine, palette.mint, 2, giftLift);
      });
    }

    // --- SCENE 2: Cozy Winter Alpine Chalet Vignette ---
    if (alphaScene2 > 0.001) {
      opacity(alphaScene2, () => {
        fir(globeX + 88, 824, 160, palette.pineDark, false);
